import pandas as pd
import numpy as np

class DataCleaning:
    def __init__(self):
        self.actions_log = []

    def clean(self, data: pd.DataFrame):
        # Verify missing values are 0% as reported and confirm no missing values in categorical columns
        for col in data.columns:
            if data[col].isnull().sum() > 0:
                if col in data['num_vars']:
                    print(f"Warning: Missing values found in numeric column {col}.")
                else:
                    print(f"Error: Missing values found in categorical column {col}.")
                    return None

        # Clip outliers in numeric columns
        self.actions_log.append("Clipping VehAge (<=20), DrivAge (<=90), BonusMalus (<=150), ClaimNb (<=5).")
        data['VehAge'] = data['VehAge'].clip(upper=20)
        data['DrivAge'] = data['DrivAge'].clip(upper=90)
        data['BonusMalus'] = data['BonusMalus'].clip(upper=150)
        data['ClaimNb'] = data['ClaimNb'].clip(upper=5)

        # Explore and normalize numeric columns
        self.actions_log.append("Checking for outliers and skewness in numeric columns.")
        for col in data['num_vars']:
            if (data[col] > 3 * data[col].mean()).any():
                self.actions_log.append(f"Outliers found in column {col}. Considering normalization or log transformation.")
                # Perform normalization or log transformation as needed
                # For simplicity, let's assume we're normalizing here
                data[col] = (data[col] - data[col].mean()) / data[col].std()

        # Categorize categorical variables
        self.actions_log.append("Encoding categorical variables.")
        for col in data['cat_vars']:
            data[col] = data[col].astype('category').cat.codes

        # Identify and address multicollinearity
        self.actions_log.append("Checking for correlations between numeric columns.")
        for col1 in data['num_vars']:
            for col2 in data['num_vars']:
                if col1!= col2 and data[col1].corr(data[col2]) > 0.7:
                    self.actions_log.append(f"High correlation found between {col1} and {col2}. Considering feature selection or dimensionality reduction.")
                    # Perform feature selection or dimensionality reduction as needed
                    # For simplicity, let's assume we're dropping one of the highly correlated columns
                    data = data.drop(columns=[col2])

        # Verify data types
        self.actions_log.append("Verifying data types.")
        for col in data.columns:
            if data[col].dtype!= pd.api.types.is_integer_dtype(data[col]) and col in data['num_vars']:
                data[col] = data[col].astype(float)

        # Data visualization
        self.actions_log.append("Creating plots to understand variable distributions.")
        # For simplicity, let's assume we're creating histograms for numeric columns and bar plots for categorical columns
        for col in data['num_vars']:
            data[col].hist()
        for col in data['cat_vars']:
            data[col].value_counts().plot(kind='bar')

        return data
